import type { Locale } from "../util";
import { createAboutSubmenu } from "./submenu/about-menu";
import { createGetFinancingSubmenu } from "./submenu/get-financing-menu";
import { createGiveFinancingSubmenu } from "./submenu/give-financing-menu";
import type { Submenu } from "./submenu/model";
import { createMyAreaSubmenu } from "./submenu/my-area-menu";

export const headerHeight = 80;

const messagesEn = {
    login: () => "Login",
    register: () => "Registration",
};
const messagesDe: typeof messagesEn = {
    login: () => "Login",
    register: () => "Registrieren",
};

export function getHeaderMessages(locale: Locale) {
    return locale == "en" ? messagesEn : messagesDe;
}

const urlsEn = {
    login: () => "/en/login",
    register: () => "/en/registration",
};
const urlsDe: typeof urlsEn = {
    login: () => "/de/anmelden",
    register: () => "/de/registration",
};

export function getHeaderUrls(locale: Locale) {
    return locale == "en" ? urlsEn : urlsDe;
}

export function getSubmenus(locale: Locale, sessionInfo: any) {
    let isLoggedIn = sessionInfo != null;

    let menu: { [key: string]: Submenu } = {
        give: createGiveFinancingSubmenu(locale, isLoggedIn),
        get: createGetFinancingSubmenu(locale),
        about: createAboutSubmenu(locale, isLoggedIn),
    };

    if (isLoggedIn) {
        menu.myArea = createMyAreaSubmenu(locale, sessionInfo);
    }

    return menu;
}
