import type { Locale } from "../../util";
import type { Submenu } from "./model";
import balance from "../icon/balance.svg";
import tasksChecked from "../icon/tasks-checked.svg";
import blackboardPointer from "../icon/blackboard-pointer.svg";


export function createGiveFinancingSubmenu(locale: Locale, isLoggedIn: boolean): Submenu {
    const en = locale === "en";
    return {
        title: en ? "Fund Legal Cases" : "Prozesse finanzieren",
        categories: [
            {
                type: "big",
                title: en ? "Current Cases" : "Aktuelle Fälle",
                href: isLoggedIn ? `/${locale}/app/lawsuit/current-cases/` : `/${locale}/overview/`,
                icon: balance,
            },
            {
                type: "big",
                title: en ? "Step-by-Step Guide" : "Step-by-Step Guide",
                href: en ? "/en/how-it-works" : "/de/ablauf-einer-prozessfinanzierung",
                icon: tasksChecked,
            },
            {
                type: "big",
                title: en ? "Video Tutorials" : "Video Tutorials",
                href: en ? "/en/videos" : "/de/videos",
                icon: blackboardPointer,
            },
            {
                type: "list",
                items: [
                    {
                        title: "FAQ",
                        href: en ? "/en/faqs/?tag=for-sponsors-en" : "/de/faqs/?tag=for-sponsors",
                    },
                    {
                        title: en ? "What is Litigation Funding" : "Was ist Prozessfinanzierung",
                        href: en ? "/en/litigation-funding" : "/de/so-funktioniert-prozessfinanzierung",
                    },
                    {
                        title: en ? "Impact" : "Impact",
                        href: en ? "/en/impact-and-return" : "/de/impact-und-rendite",
                    },
                ],
            },
        ],
    };
}
