<script lang="ts">
    let { show, children } = $props();

    $effect(() => {
        if (show) enableBodyScrollLock();
        else disableBodyScrollLock();
    });

    let scrollOffset: number;
    const scrollElement = document.scrollingElement as HTMLBodyElement;

    function enableBodyScrollLock() {
        scrollOffset = window.pageYOffset;

        scrollElement.style.overflow = "hidden";
        scrollElement.style.position = "fixed";
        scrollElement.style.top = -scrollOffset + "px";
    }

    function disableBodyScrollLock() {
        scrollElement.style.removeProperty("position");
        scrollElement.style.removeProperty("overflow");
        scrollElement.style.removeProperty("top");

        window.scrollTo(0, scrollOffset);
    }
</script>

<div style:transform={`translateX(${show ? "0" : "-101%"})`} class="hdr-screen-overlay">
    {@render children?.()}
</div>

<style>
    .hdr-screen-overlay {
        position: fixed;
        top: 0;
        left: 0;
        width: 100dvw;
        height: 100dvh;
        z-index: 1000;
        background-color: #fff;
        transition: transform 0.4s;
    }
</style>
