<script lang="ts">
    import Header from "./ui/Header.svelte";

    const locale = document.location.pathname.startsWith("/de") ? "de" : "en";

    const isDev = import.meta.env.MODE == "development";
    const isServer = import.meta.env.SSR;
    const apiPrefix = isDev ? "http://localhost:8000" : "";
    const cacheKey = "sessionInfo";

    let sessionInfo: any = $state(null);

    function restoreCachedSessionInfo() {
        const cached = sessionStorage.getItem(cacheKey);
        if (cached) {
            sessionInfo = JSON.parse(cached);
        }
    }

    async function fetchSessionInfo() {
        const resp = await fetch(`${apiPrefix}/${locale}/api/session/info`, {
            credentials: "include",
        });

        if (resp.status == 200) {
            sessionInfo = await resp.json();
            sessionStorage.setItem(cacheKey, JSON.stringify(sessionInfo));
        } else {
            sessionInfo = null;
            sessionStorage.removeItem(cacheKey);
        }
    }

    if (!isServer) {
        restoreCachedSessionInfo();
        fetchSessionInfo();
        // sessionInfo = testSessionInfo;
    }
</script>

<Header browser={true} {locale} {sessionInfo} />
