import { hydrate, mount } from 'svelte';
import './app.css';
import App from './App.svelte';

const isDev = import.meta.env.MODE == "development";


let app;
if (isDev) {
  app = mount(App, {
    target: document.getElementById('aqf-header-app')!,
  })
} else {
  app = hydrate(App, {
    target: document.querySelector('#aqf-header-app')!!,
  });
}

export default app
