import { getContext } from "svelte";

export const browser = !(typeof document === 'undefined');

export type Locale = "en" | "de";

export function getLocale(): Locale {
    return getContext("locale");
}

/**
 * Return the absolute URL of the page in the requested locale, taken from the
 * <link rel="alternate" hreflang="…"> tag that Symfony/Wordpress rendered.
 */
export function getTranslatedUrl(locale: Locale): string {
    const fallbackPath = '/' + locale;

    if (browser) {
        const linkTag = document.querySelector<HTMLLinkElement>(`link[rel="alternate"][hreflang="${locale}"]`);
        return linkTag?.href ?? fallbackPath;
    } else {
        return fallbackPath;
    }
}
