<script lang="ts">
    import { untrack, type Snippet } from "svelte";
    import { headerHeight } from "./header-menu";

    interface Props {
        label: string;
        children: Snippet;
        requestShow: () => void;
        requestHide: () => void;
    }
    let { label, children, requestShow, requestHide }: Props = $props();

    let visible = $state(false);

    export function setVisible(_visible: boolean) {
        // console.log("setVisible", _visible);
        visible = _visible;
    }

    function toggle() {
        if (visible) requestHide();
        else requestShow();
    }

    let mouseOverLabel = $state(false);
    let mouseOverRibbon = $state(false);
    // $inspect("mouseOverLabel", mouseOverLabel);
    // $inspect("mouseOverRibbon", mouseOverRibbon);

    let hideTimeout: any | null = null;
    function scheduleHide() {
        if (hideTimeout) clearTimeout(hideTimeout);
        hideTimeout = setTimeout(() => requestHide(), 500);
    }

    $effect(() => {
        const hover = mouseOverLabel || mouseOverRibbon;
        untrack(() => {
            // console.log(`effect hove: ${hover}, visible: ${visible}`);
            if (hover) {
                clearTimeout(hideTimeout);
                if (!visible) requestShow();
            } else {
                if (visible) scheduleHide();
            }
        });
    });
</script>

<!-- svelte-ignore a11y_interactive_supports_focus -->
<div
    class="hdr-label"
    class:hdr-label-active={visible}
    ontouchend={(e) => toggle()}
    onmouseenter={() => (mouseOverLabel = true)}
    onmouseleave={() => (mouseOverLabel = false)}
    onkeyup={(e) => toggle()}
    role="tab"
    aria-selected={visible}
>
    {label}
</div>

<!-- svelte-ignore a11y_interactive_supports_focus -->
<div
    class="hdr-ribbon"
    class:hdr-ribbon-visible={visible}
    style:left="0px"
    style:top={`${headerHeight}px`}
    onmouseenter={() => (mouseOverRibbon = true)}
    onmouseleave={() => (mouseOverRibbon = false)}
    role="tabpanel"
>
    {@render children?.()}
</div>

<style>
    .hdr-label {
        display: flex;
        align-items: center;
        padding: 0 16px;
        margin: 0 2px;
        height: 100%;
        text-wrap: nowrap;
        cursor: pointer;
    }

    @media screen and (max-width: 1199px) {
        .hdr-label {
            padding: 0 10px;
        }
    }

    .hdr-label-active {
        background-color: #efefef;
    }

    .hdr-ribbon {
        position: absolute;
        background-color: #efefef;
        min-height: 218px;
        width: 100%;

        transform: translate(0, -140%);
        transition: transform 0.4s;
        z-index: -10;
    }
    .hdr-ribbon-visible {
        transform: translate(0);
    }
</style>
