<script lang="ts">
  import { getLocale } from "../util";
  import DesktopRibbon from "./DesktopRibbon.svelte";
  import DesktopSubmenu from "./DesktopSubmenu.svelte";
  import { getHeaderMessages, getHeaderUrls, getSubmenus, headerHeight } from "./header-menu";
  import burgerIcon from "./icon/hamburger-menu-1.svg";
  import LanguageSelector from "./LanguageSelector.svelte";
  import Logo from "./logo/Logo.svelte";

  interface Props {
    sessionInfo: any | null;
    requestShow: () => void;
  }
  const { sessionInfo, requestShow }: Props = $props();

  let isLoggedIn = $derived(sessionInfo != null);
  let submenus = $derived(getSubmenus(getLocale(), sessionInfo));
  let ribbons: { [key: string]: DesktopRibbon } = $state({});

  const m = getHeaderMessages(getLocale());
  const url = getHeaderUrls(getLocale());

  function showRibbon(ribbon: DesktopRibbon) {
    Object.values(ribbons).forEach((r) => r?.setVisible(false));
    ribbon.setVisible(true);
  }
</script>

{#snippet ribbonDropdown(key: string)}
  <DesktopRibbon
    label={submenus[key].title}
    bind:this={ribbons[key]}
    requestShow={() => showRibbon(ribbons[key])}
    requestHide={() => ribbons[key].setVisible(false)}
  >
    <DesktopSubmenu submenu={submenus[key]}></DesktopSubmenu>
  </DesktopRibbon>
{/snippet}

<div style:height={`${headerHeight}px`} style:background-color="rgba(255, 255, 255, 0.94)">
  <div class="hdr-mobile-bar">
    <div style:flex="1" role="button" tabindex="0" onclick={() => requestShow()} onkeyup={() => requestShow()}>
      <img src={burgerIcon} style="height: 16px; margin-left: 20px; margin-top: 5px;" alt="Menu" />
    </div>

    <div style="flex: 2; display: flex; justify-content: center;">
      <Logo/>
    </div>

    <div style:flex="1"></div>
  </div>

  <div class="hdr-desktop-bar">
    <div style="display: flex; flex-direction: row; align-items: center;">
      <div style="margin-left: 30px; margin-right: 20px;">
        <Logo/>
      </div>

      <div style="display: flex; flex-direction: row; align-items: center; height: 100%;">
        {@render ribbonDropdown("give")}
        {@render ribbonDropdown("get")}
        {@render ribbonDropdown("about")}
      </div>
    </div>

    <div style="display: flex; flex-direction: row; align-items: center;">
      <div style="margin: 0px 10px;">
        <LanguageSelector />
      </div>

      {#if isLoggedIn}
        <div style="height: 100%;">
          {@render ribbonDropdown("myArea")}
        </div>

        {#if sessionInfo?.admin}
          <div>
            <a href="/backoffice/dashboard">Back office</a>
          </div>
        {/if}
      {:else}
        <div style="margin: 0 10px;">
          <a href={url.login()} class="hdr-button-secondary">{m.login()}</a>
        </div>
        <div style="margin-left: 10px; margin-right: 25px;">
          <a href={url.register()} class="hdr-button-primary">{m.register()}</a>
        </div>
      {/if}
    </div>
  </div>
</div>

<style>
  .hdr-desktop-bar {
    display: flex;
    flex-direction: row;
    justify-content: space-between;
    width: 100%;
    height: 100%;
  }

  .hdr-mobile-bar {
    display: none;
    flex-direction: row;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    height: 100%;
  }

  @media screen and (max-width: 1023px) {
    .hdr-desktop-bar {
      display: none;
    }
    .hdr-mobile-bar {
      display: flex;
    }
  }
</style>
