import type { Locale } from "../../util";
import type { Category, Submenu } from "./model";

export function createMyAreaSubmenu(locale: Locale, sessionInfo: any): Submenu {
    const en = locale === "en";
    const items = sessionInfo.menuItems.map((item: any) => ({
        title: item.label,
        href: item.link,
    }));

    const categories: Category[] = [];

    // First three categories: max 3 items each
    for (let i = 0; i < 3; i++) {
        const offset = i * 3;
        const slice = items.slice(offset, offset + 3);
        if (slice.length > 0) {
            categories.push({
                type: "list",
                items: slice,
            });
        }
    }

    // Fourth category: remaining items
    const remaining = items.slice(9);
    if (remaining.length > 0) {
        categories.push({
            type: "list",
            items: remaining,
        });
    }

    return {
        title: en ? "My Area" : "Mein Bereich",
        categories,
    };
}
