<script lang="ts">
    import { onDestroy, onMount, setContext } from "svelte";
    import type { Locale } from "../util";
    import { headerHeight } from "./header-menu";
    import HeaderBar from "./HeaderBar.svelte";
    import MobileMenu from "./MobileMenu.svelte";
    import MobileOverlay from "./MobileOverlay.svelte";

    interface Props {
        browser: boolean;
        locale: Locale;
        sessionInfo: any | null;
    }
    const { browser, locale, sessionInfo }: Props = $props();

    setContext("locale", locale);

    let showMobileMenu = $state(false);
    let showHeader = $state(true);

    let previousScrollPosition = NaN;

    /** the smallest scroll position reached when last scrolling up */
    let smallestScrollPosition = previousScrollPosition;

    function handleScroll() {
        const currentScrollPosition = window.pageYOffset;
        const scrollingUp = currentScrollPosition < previousScrollPosition;

        if (scrollingUp) {
            // show immediately
            showHeader = true;
            smallestScrollPosition = previousScrollPosition;
        } else {
            // show when some distance is reached
            if (currentScrollPosition > headerHeight && currentScrollPosition > smallestScrollPosition + 40) {
                showHeader = false;
            }
        }

        previousScrollPosition = currentScrollPosition;
    }

    if (browser) {
        previousScrollPosition = window.pageYOffset;
        smallestScrollPosition = previousScrollPosition;

        onMount(() => {
            window.addEventListener("scroll", handleScroll);
        });

        onDestroy(() => {
            window.removeEventListener("scroll", handleScroll);
        });
    }
</script>

<header class="hdr-root" style:height={`${headerHeight}px`}>
    <div
        style="position: fixed; top: 0; left: 0; width: 100vw; z-index: 1000; transition: transform 300ms ease-in-out;"
        style:transform={showHeader ? "translateY(0)" : "translateY(-100%)"}
    >
        <HeaderBar {sessionInfo} requestShow={() => (showMobileMenu = true)} />
    </div>

    <MobileOverlay show={showMobileMenu}>
        <MobileMenu {sessionInfo} requestClose={() => (showMobileMenu = false)} visible={showMobileMenu}></MobileMenu>
    </MobileOverlay>
</header>

<style>
    .hdr-root {
        font-family: "Roboto", sans-serif;
        font-size: 17px;
        font-weight: 300;
        font-style: normal;
        line-height: normal;
        background-color: #fff;
        color: #323232;
        display: block;
    }

    @media screen and (max-width: 1199px) {
        .hdr-root {
            font-size: 15px;
        }
    }
</style>
