import type { Locale } from "../../util";
import type { Submenu } from "./model";
import handCoins from "../icon/hand-coins.svg";
import calculator from "../icon/calculator.svg";

export function createGetFinancingSubmenu(locale: Locale): Submenu {
    const en = locale === "en";
    return {
        title: en ? "Get Financing" : "Prozessfinanzierung erhalten",
        categories: [
            {
                // One wizard for private and company alike — it replaced the
                // separate /submit-private and /submit-company forms.
                type: "big",
                title: en ? "Case Enquiry" : "Fallanfrage",
                href: `/${locale}/case-inquiry`,
                icon: handCoins,
            },
            {
                type: "big",
                title: en ? "Litigation Cost Calculator" : "Prozesskostenrechner",
                href: en ? "/en/litigation-cost-calculator" : "/de/prozesskostenrechner",
                icon: calculator,
            },
            {
                type: "list",
                items: [
                    {
                        title: en ? "Step-by-Step Guide" : "Step-by-Step Guide",
                        href: en ? "/en/how-it-works" : "/de/ablauf-einer-prozessfinanzierung",
                    },
                    {
                        title: en ? "FAQ" : "FAQ",
                        href: en ? "/en/faqs/?tag=for-litigants" : "/de/faqs/?tag=for-litigants-de",
                    },
                    {
                        title: en ? "Video Tutorials" : "Video Tutorials",
                        href: en ? "/en/videos" : "/de/videos",
                    },
                ],
            },
        ],
    };
}