<!-- svelte-ignore a11y_click_events_have_key_events -->
<!-- svelte-ignore a11y_interactive_supports_focus -->

<script lang="ts">
    import { getLocale } from "../util";
    import LanguageSelector from "./LanguageSelector.svelte";
    import Logo from "./logo/Logo.svelte";
    import { getHeaderMessages, getHeaderUrls, getSubmenus } from "./header-menu";
    import arrowLeft from "./icon/arrow-1-left.svg";
    import arrowRight from "./icon/arrow-1-right.svg";
    import closeIcon from "./icon/close.svg";
    import type { Submenu } from "./submenu/model";

    interface Props {
        sessionInfo: any | null;
        requestClose: () => void;
        visible: boolean;
    }
    const { sessionInfo, requestClose, visible }: Props = $props();

    let isLoggedIn = $derived(sessionInfo != null);
    let inactiveSubmenuTranslateX = $derived(visible ? 101 : 201);

    const m = getHeaderMessages(getLocale());
    const url = getHeaderUrls(getLocale());

    let submenus = $derived(getSubmenus(getLocale(), sessionInfo));
    let activeSubmenu: string | null = $state(null);

    function getFlatSubmenu(submenu: Submenu): any[] {
        return submenu.categories.flatMap((c) => {
            if (c.type == "big") {
                return [c];
            } else {
                return c.items;
            }
        });
    }
</script>

<div style="display: flex; flex-direction: column; width: 100%; height: 100%; font-size: 17px;">
    <div style="flex: 0;">
        <div
            style="height: 60px; display:flex; flex-direction: row;  padding: 10px 20px; align-items: center; border-bottom: 1px solid #CCC;"
        >
            <div style="flex: 1;">
                {#if activeSubmenu != null}
                    <div onclick={(e) => (activeSubmenu = null)} role="button">
                        <img src={arrowLeft} style="height: 40px;" alt="Back" />
                    </div>
                {/if}
            </div>
            <div style="flex: 2; display: flex; justify-content: center;">
                {#if activeSubmenu != null}
                    {submenus[activeSubmenu]!.title}
                {:else}
                <Logo/>
                {/if}
            </div>
            <div style="flex: 1; display: flex; justify-content: flex-end;">
                <div onclick={requestClose} role="button">
                    <img src={closeIcon} style="height: 20px;" alt="Close" />
                </div>
            </div>
        </div>
    </div>

    <div style="flex: 1;">
        <div style="position: relative; width: 100%; height: 100%;">
            <div class="hdr-menu-card">
                {#each Object.entries(submenus) as [key, submenu]}
                    <div class="hdr-menu-item" onclick={(e) => (activeSubmenu = key)} role="button">
                        <div
                            style="display: flex; flex-direction: row; align-items: center; justify-content: space-between; padding: 15px 0;"
                        >
                            <span>{submenu.title}</span>
                            <img src={arrowRight} style="height: 40px;" alt="Open" />
                        </div>
                    </div>
                {/each}
            </div>

            {#each Object.entries(submenus) as [key, submenu]}
                <div
                    class="hdr-menu-card"
                    style:transition="transform 0.4s"
                    style:transform={`translateX(${activeSubmenu === key ? "0%" : inactiveSubmenuTranslateX + "%"})`}
                >
                    {#each getFlatSubmenu(submenu) as item}
                        <div class="hdr-menu-item">
                            <a href={item.href}>
                                <div
                                    style="display: flex; flex-direction: row; align-items: center; justify-content: space-between;"
                                    style:height={item.icon ? "70px" : "30px"}
                                >
                                    <div>{item.title}</div>

                                    {#if item.icon}
                                        <div>
                                            <img src={item.icon} alt="Icon" style="height: 40px;" />
                                        </div>
                                    {/if}
                                </div>
                            </a>
                        </div>
                    {/each}
                </div>
            {/each}
        </div>
    </div>

    <div style="flex: 0; display: flex; flex-direction: row; padding: 20px 20px; align-items: center; justify-content: space-between;">
        <div class="hdr-desktop-only">
            <LanguageSelector />
        </div>

        <div style="display: flex; flex-direction: row;">
            {#if isLoggedIn}
                {#if sessionInfo?.admin}
                    <div>
                        <a href="/backoffice/dashboard">Back office</a>
                    </div>
                {/if}
            {:else}
                <div class="" style="margin: 0 20px;">
                    <a href={url.login()} class="hdr-button-secondary">{m.login()}</a>
                </div>
                <div class="" style="">
                    <a href={url.register()} class="hdr-button-primary">{m.register()}</a>
                </div>
            {/if}
        </div>
    </div>
</div>

<style>
    .hdr-menu-card {
        position: absolute;
        top: 0;
        width: 100%;
        height: 100%;
        overflow-y: scroll;
        background-color: #fff;
    }

    .hdr-menu-item {
        padding-top: 15px;
        padding-bottom: 14px;
        border-bottom: 1px solid #ccc;
        margin: 0 20px;
        cursor: pointer;
    }
</style>
